def isbn_valid(s: str) -> bool:
    # Remove hyphens and spaces as required.
    if not isinstance(s, str):
        return False
    s = s.replace("-", "").replace(" ", "")

    if len(s) == 10:
        if not all(ch in "0123456789" for ch in s[:9]):
            return False
        if s[9] not in "0123456789X":
            return False

        values = [int(ch) for ch in s[:9]]
        values.append(10 if s[9] == "X" else int(s[9]))
        return sum((i + 1) * value for i, value in enumerate(values)) % 11 == 0

    if len(s) == 13:
        if not all(ch in "0123456789" for ch in s):
            return False
        return sum(
            int(ch) * (1 if i % 2 == 0 else 3)
            for i, ch in enumerate(s)
        ) % 10 == 0

    return False
